 WHERE @mms_instance = 'SG' AND TRIM(p.sku) = 'C1426' AND t.attribute_id = @a AND LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<a href="https://azure.microsoft.com/en-us/" title="Azure Cloud Computing account" target="_blank">free Microsoft Azure account (https://azure.microsoft.com/en-us/)</a> here&nbsp;</p>\r\n<p><strong>Hardware:</strong>&nbsp;Window or Mac Laptops</p>', t.value) > 0;

