 WHERE @mms_instance = 'SG' AND TRIM(p.sku) = 'C923' AND t.attribute_id = @a AND LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<ul>\r\n<li>&nbsp;<a href="https://store.docker.com/editions/community/docker-ce-desktop-windows" title="Docker for Windows" target="_blank">Docker (Windows)</a></li>\r\n<li>&nbsp;<a href="https://store.docker.com/editions/community/docker-ce-desktop-mac%20" title="Docker for Mac" target="_blank">Docker (Mac)&nbsp;</a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong>&nbsp;Window or&nbsp;Mac&nbsp;Laptops</p>', t.value) > 0;

