   SET t.value = CONCAT(LEFT(t.value, LOCATE('<h2>Minimum Software/Hardware Requirement</h2><p><strong>Software:</strong> NIL</p><p><strong>Hardware:</strong> Windows and Mac Laptops</p>', t.value) - 1), '<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You will need the following for this course:</p>\r\n<ul>\r\n<li>A free account on a generative AI assistant of your choice, e.g. <a href="https://chatgpt.com/" target="_blank">ChatGPT</a>, <a href="https://gemini.google.com/" target="_blank">Google Gemini</a> or <a href="https://copilot.microsoft.com/" target="_blank">Microsoft Copilot</a> (the free tier is sufficient)</li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\r\n', SUBSTRING(t.value, LOCATE('<h2>Minimum Software/Hardware Requirement</h2><p><strong>Software:</strong> NIL</p><p><strong>Hardware:</strong> Windows and Mac Laptops</p>', t.value) + CHAR_LENGTH('<h2>Minimum Software/Hardware Requirement</h2><p><strong>Software:</strong> NIL</p><p><strong>Hardware:</strong> Windows and Mac Laptops</p>')))
