-- TGS-2024049212
UPDATE catalog_product_entity_text t JOIN catalog_product_entity p ON p.entity_id = t.entity_id
   SET t.value = CONCAT(LEFT(t.value, LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<ul>\r\n<li><strong>Laptop:</strong>&nbsp;Learners are required to have a laptop for the training sessions. This is essential for hands-on practice and completing lab exercises.</li>\r\n<li><strong>Software:</strong>&nbsp;The course will involve the use of various Linux distributions and tools. Learners will need to install and configure Linux environments, manage software, storage, processes, and services. They will also work with scripting, containerization, and automation tools.</li>\r\n<li>V<strong>irtual Labs:</strong>&nbsp;Virtual labs that simulate real-world environments will be provided to the learners. These labs allow learners to practice tasks such as configuring and managing Linux systems, troubleshooting issues, and performing security best practices</li>\r\n</ul>\r\n', t.value) - 1), '<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You will need the following for this course:</p>\r\n<ul>\r\n<li><a href="https://www.microsoft.com/en-sg/microsoft-365/excel" target="_blank">Microsoft Excel (desktop app, Microsoft 365)</a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\r\n', SUBSTRING(t.value, LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<ul>\r\n<li><strong>Laptop:</strong>&nbsp;Learners are required to have a laptop for the training sessions. This is essential for hands-on practice and completing lab exercises.</li>\r\n<li><strong>Software:</strong>&nbsp;The course will involve the use of various Linux distributions and tools. Learners will need to install and configure Linux environments, manage software, storage, processes, and services. They will also work with scripting, containerization, and automation tools.</li>\r\n<li>V<strong>irtual Labs:</strong>&nbsp;Virtual labs that simulate real-world environments will be provided to the learners. These labs allow learners to practice tasks such as configuring and managing Linux systems, troubleshooting issues, and performing security best practices</li>\r\n</ul>\r\n', t.value) + CHAR_LENGTH('<h2>Minimum Software/Hardware Requirement</h2>\r\n<ul>\r\n<li><strong>Laptop:</strong>&nbsp;Learners are required to have a laptop for the training sessions. This is essential for hands-on practice and completing lab exercises.</li>\r\n<li><strong>Software:</strong>&nbsp;The course will involve the use of various Linux distributions and tools. Learners will need to install and configure Linux environments, manage software, storage, processes, and services. They will also work with scripting, containerization, and automation tools.</li>\r\n<li>V<strong>irtual Labs:</strong>&nbsp;Virtual labs that simulate real-world environments will be provided to the learners. These labs allow learners to practice tasks such as configuring and managing Linux systems, troubleshooting issues, and performing security best practices</li>\r\n</ul>\r\n')))
 WHERE @mms_instance = 'SG' AND TRIM(p.sku) = 'TGS-2024049212' AND t.attribute_id = @a AND LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<ul>\r\n<li><strong>Laptop:</strong>&nbsp;Learners are required to have a laptop for the training sessions. This is essential for hands-on practice and completing lab exercises.</li>\r\n<li><strong>Software:</strong>&nbsp;The course will involve the use of various Linux distributions and tools. Learners will need to install and configure Linux environments, manage software, storage, processes, and services. They will also work with scripting, containerization, and automation tools.</li>\r\n<li>V<strong>irtual Labs:</strong>&nbsp;Virtual labs that simulate real-world environments will be provided to the learners. These labs allow learners to practice tasks such as configuring and managing Linux systems, troubleshooting issues, and performing security best practices</li>\r\n</ul>\r\n', t.value) > 0;

