   SET t.value = CONCAT(LEFT(t.value, LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You can download and install the following software:</p>\r\n<ul>\r\n<li><a href="https://www.microsoft.com/en-sg/microsoft-365/excel" target="_blank"><span style="text-decoration: underline;">Excel</span></a></li>\r\n<li><a href="https://www.microsoft.com/en-sg/download/details.aspx?id=39379" target="_blank"><span style="text-decoration: underline;">Power Query</span></a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows and Mac Laptops</p>\r\n', t.value) - 1), '<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You will need the following for this course:</p>\r\n<ul>\r\n<li><a href="https://www.microsoft.com/en-sg/microsoft-365/excel" target="_blank">Microsoft Excel (desktop app, Microsoft 365)</a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows PC or Mac laptop</p>\r\n', SUBSTRING(t.value, LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You can download and install the following software:</p>\r\n<ul>\r\n<li><a href="https://www.microsoft.com/en-sg/microsoft-365/excel" target="_blank"><span style="text-decoration: underline;">Excel</span></a></li>\r\n<li><a href="https://www.microsoft.com/en-sg/download/details.aspx?id=39379" target="_blank"><span style="text-decoration: underline;">Power Query</span></a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows and Mac Laptops</p>\r\n', t.value) + CHAR_LENGTH('<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You can download and install the following software:</p>\r\n<ul>\r\n<li><a href="https://www.microsoft.com/en-sg/microsoft-365/excel" target="_blank"><span style="text-decoration: underline;">Excel</span></a></li>\r\n<li><a href="https://www.microsoft.com/en-sg/download/details.aspx?id=39379" target="_blank"><span style="text-decoration: underline;">Power Query</span></a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows and Mac Laptops</p>\r\n')))
 WHERE @mms_instance = 'SG' AND TRIM(p.sku) = 'TGS-2026064861' AND t.attribute_id = @a AND LOCATE('<h2>Minimum Software/Hardware Requirement</h2>\r\n<p><strong>Software:</strong></p>\r\n<p>You can download and install the following software:</p>\r\n<ul>\r\n<li><a href="https://www.microsoft.com/en-sg/microsoft-365/excel" target="_blank"><span style="text-decoration: underline;">Excel</span></a></li>\r\n<li><a href="https://www.microsoft.com/en-sg/download/details.aspx?id=39379" target="_blank"><span style="text-decoration: underline;">Power Query</span></a></li>\r\n</ul>\r\n<p><strong>Hardware:</strong> Windows and Mac Laptops</p>\r\n', t.value) > 0;

